const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let en=localStorage.getItem('signal-ui')==='en',local=false,data,ws='demo',page='diagnostic',filter={market:'us',platform:'',search:'',from:'',to:''},preview=[],lastFocus;
const enc=s=>encodeURIComponent(s).replace(/'/g,'%27');
const t=(a,b)=>en?b:a,uid=()=>crypto.randomUUID(),now=()=>new Date().toISOString();
const names={overview:['工作区总览','Overview'],markets:['市场与 AI 覆盖','Markets & AI coverage'],entities:['商品与门店','Products & locations'],visibility:['可见度分析','Visibility'],prompts:['问题与题集','Prompts'],executions:['回答与证据','Answers & evidence'],citations:['引用分析','Citations'],projects:['机会与项目','Projects'],content:['内容与审核','Content & review'],experiments:['复测与报告','Experiments & reports'],knowledge:['知识与事实','Knowledge & facts'],integrations:['连接中心','Integrations'],settings:['工作区设置','Settings'],audit:['操作记录','Activity log'],factcheck:['事实核查','Fact check'],sentiment:['品牌评价','Sentiment'],fanout:['检索展开','Query fan-out'],demand:['需求研究','Demand'],shopping:['购物监测','Shopping'],traffic:['机器人与访问','Agent analytics'],automations:['Agents 与 Workflows','Agents & workflows'],runs:['运行记录','Runs']};
const title=k=>names[k]?.[en?1:0]||k;
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${({overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',markets:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',visibility:'<path d="M3 17l6-7 5 3 7-9M3 21h18"/>',prompts:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',citations:'<path d="M10 14l4-4m-7 5l-2 2a4 4 0 005 5l4-4m-4-8l4-4a4 4 0 016 6l-2 2"/>',projects:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M8 6V3h8v3M3 12h18"/>',knowledge:'<path d="M12 5v16M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2z"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10l2 2M5 19l2-2M17 7l2-2"/>'})[n]||'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 13h8M8 17h4"/>'}</svg>`;
function seed(){const prompts=[['p1','What are the best refillable hand soaps for a small apartment?','Hand soap','us','en'],['p2','Which plastic-free laundry tablets work in cold water?','Laundry','us','en'],['p3','Best zero-waste cleaning starter kits for a family?','Starter kits','us','en'],['p4','How do refillable soap tablets compare with liquid soap?','Hand soap','us','en'],['p5','杭州滨江适合远程办公的咖啡店有哪些？','工作场景','cn','zh'],['p6','杭州滨江周末有户外座位的咖啡店推荐','门店选择','cn','zh']].map(([id,text,topic,market,locale])=>({id,text,topic,market,locale,type:'discovery',version:1,history:[],active:true}));
let answers=[];for(let d=0;d<7;d++)for(let i=0;i<6;i++){let p=prompts[i],yes=(d+i)%4!==0,fail=(d+i)%13===0,cn=p.market==='cn';answers.push({id:'a'+d+'-'+i,prompt_id:p.id,prompt_text:p.text,topic:p.topic,prompt_version:1,market:p.market,locale:p.locale,platform:cn?(i%2?'Kimi · Web':'豆包 · Web'):['ChatGPT · Search','Perplexity · Search','Claude · Web'][i%3],collected_at:`2026-10-${String(11+d).padStart(2,'0')}T14:00:00Z`,status:fail?'failed':'success',raw_answer:fail?'':cn?(yes?'示例回答：Aster Home 体验店（虚构品牌）可作为备选。请在到店前核实营业时间、座位及插座情况。此文本仅演示原文证据链，不来自实际平台。':'示例回答：建议先比较商圈内店铺的座位、环境与营业时间。此条未点名目标品牌，仅用于交互演示。'):(yes?'Illustrative answer: Aster Home (a fictional brand) is one option for refillable household products. Compare the exact pack size, usage conditions and independent reviews before choosing. This is synthetic demo text, not a captured AI answer.':'Illustrative answer: Compare refill formats, ingredients and total purchase conditions. The target brand is absent from this synthetic example.'),source_type:'demo',collection_region:null,citation_supported:true,citation_complete:true,citation_type:'web_panel',citations:fail?[]:[{url:yes?(cn?'https://qingyu.example/locations/binjiang':'https://aster.example/products/refill'):'https://review.example/refill-comparison',title:cn?'门店资料示例':'Refill product information · Example',role:yes?'owned':'unknown',support:yes?'Compare exact conditions before choosing.':''}]});}
return {workspaces:[{id:'demo',name:'Aster Home',brand:'Aster Home',aliases:['Aster Home'],domains:['aster.example','qingyu.example'],demo:true},{id:'real',name:'我的品牌',brand:'我的品牌',aliases:['我的品牌'],domains:[],demo:false}],prompts:prompts.map(p=>({...p,workspace:'demo'})),answers:answers.map(a=>({...a,workspace:'demo'})),projects:[],facts:[],artifacts:[],experiments:[],audit:[],revision:1};}
function workspace(){return data.workspaces.find(w=>w.id===ws)}function rows(key){return data[key].filter(x=>x.workspace===ws)}
function filtered(){return rows('answers').filter(a=>(!filter.market||a.market===filter.market)&&(!filter.platform||a.platform===filter.platform)&&(!filter.from||a.collected_at.slice(0,10)>=filter.from)&&(!filter.to||a.collected_at.slice(0,10)<=filter.to)&&(!filter.search||(a.prompt_text+' '+a.raw_answer+' '+a.topic).toLowerCase().includes(filter.search.toLowerCase())))}
function mentioned(a){return workspace().aliases.some(n=>{const txt=a.raw_answer.toLocaleLowerCase(),term=n.toLocaleLowerCase();if(!term)return false;if(/^[\x00-\x7F]+$/.test(term)){const r=new RegExp('(^|[^a-z0-9])'+term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?=$|[^a-z0-9])','i');return r.test(txt)}return txt.includes(term)})}
function citations(a){const seen=new Set();return(a.citations||[]).filter(c=>{if(!safeURL(c.url)||seen.has(c.url))return false;seen.add(c.url);return true})}function owned(c){try{return workspace().domains.some(d=>new URL(c.url).hostname===d||new URL(c.url).hostname.endsWith('.'+d))}catch{return false}}
function metric(arr=filtered()){let valid=arr.filter(a=>a.status==='success'&&!a.truncated&&!a.cached&&(!a.prompt_type||a.prompt_type==='discovery')),m=valid.filter(mentioned).length,cap=valid.filter(a=>a.citation_supported===true&&a.citation_complete===true&&['api_native','web_panel'].includes(a.citation_type)),o=cap.filter(a=>citations(a).some(owned)).length;return{valid,m,cap,o,failed:arr.filter(a=>a.status==='failed').length,rate:valid.length?m/valid.length:null,own:cap.length?o/cap.length:null}}
const pct=(n)=>n===null?'—':(n*100).toFixed(1)+'%',safeURL=u=>{try{return ['https:','http:'].includes(new URL(u).protocol)}catch{return false}};
function nav(k){return `<a href="#/w/${ws}/${k}" class="${page===k?'active':''}">${icon(k)}${title(k)}</a>`}function query(){return new URLSearchParams(Object.entries(filter).filter(([k,v])=>v)).toString()}function syncURL(){const q=new URLSearchParams(query());const old=new URLSearchParams(location.hash.split('?')[1]);if(old.has('answer'))q.set('answer',old.get('answer'));history.replaceState(null,'',`#/w/${ws}/${page}?${q}`)}function go(k,extra=''){location.hash=`/w/${ws}/${k}?${query()}`}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
async function mutate(action,payload){try{if(local){const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workspace:ws,action,payload,revision:data.revision})});const j=await r.json();if(!r.ok)throw Error(j.error);data=j;}else{if(ws!=='demo')throw Error(t('真实工作区需要本地服务','Real workspace requires the local server'));applyDemo(action,payload);data.revision++;}render();return true}catch(e){toast(e.message);return false}}
function applyDemo(action,p){const stamp={id:uid(),workspace:ws,created_at:now()};if(action==='project')data.projects.unshift({...stamp,...p,status:'triage'});if(action==='fact')data.facts.unshift({...stamp,...p,status:'needs_review',version:1});if(action==='approve_fact')rows('facts').find(f=>f.id===p.id).status='approved';if(action==='prompt')data.prompts.push({...stamp,...p,version:1,history:[],active:true});if(action==='edit_prompt'){let x=rows('prompts').find(x=>x.id===p.id);x.history.push({version:x.version,text:x.text});x.version++;x.text=p.text}if(action==='toggle_prompt'){let x=rows('prompts').find(x=>x.id===p.id);x.active=!x.active}if(action==='draft'){const facts=rows('facts').filter(f=>f.status==='approved'&&f.market===p.market);if(!facts.length)throw Error(t('请先批准适用市场的事实','Approve facts for this market first'));data.artifacts.unshift({...stamp,...p,version:1,status:'draft',body:facts.map(f=>f.text+' ['+f.id.slice(0,6)+']').join('\n\n'),facts:facts.map(f=>f.id),history:[]})}if(action==='save_artifact'){let a=rows('artifacts').find(a=>a.id===p.id);a.history.push({version:a.version,body:a.body,status:a.status});Object.assign(a,{body:p.body,target:p.target,version:a.version+1,status:'draft',approval:null})}if(action==='artifact_status'){let a=rows('artifacts').find(a=>a.id===p.id);if(p.status==='in_review'&&a.status!=='draft'||p.status==='approved'&&a.status!=='in_review')throw Error('Invalid transition');a.status=p.status;if(p.status==='approved')a.approval={version:a.version,at:now()}}if(action==='receipt'){let a=rows('artifacts').find(a=>a.id===p.id);if(a.status!=='approved')throw Error('Approval required');a.status='applied';a.receipt={...p,at:now()}}if(action==='experiment')data.experiments.unshift({...stamp,...p,status:'planned',baseline:metric().valid.map(a=>a.id)});data.audit.unshift({...stamp,action,object:p.id||p.title||p.text||''});}
function filters(){const platforms=[...new Set(rows('answers').filter(a=>a.market===filter.market).map(a=>a.platform))];return `<div class="filters"><select id="market" aria-label="${t('目标市场','Target market')}"><option value="us" ${filter.market==='us'?'selected':''}>${t('美国市场','United States')}</option><option value="cn" ${filter.market==='cn'?'selected':''}>${t('中国大陆市场','Mainland China')}</option></select><select id="platform" aria-label="${t('AI 产品模式','AI product mode')}"><option value="">${t('全部 AI 产品模式','All AI modes')}</option>${platforms.map(p=>`<option ${filter.platform===p?'selected':''}>${esc(p)}</option>`).join('')}</select><input id="from" type="date" aria-label="${t('开始日期','From')}" value="${filter.from}"><input id="to" type="date" aria-label="${t('结束日期','To')}" value="${filter.to}"><button class="small" onclick="resetFilters()">${t('重置筛选','Reset filters')}</button><span class="tag">${t('样本加权 · 发现型问题','Sample weighted · Discovery prompts')}</span></div>`}
function resetFilters(){filter={market:filter.market,platform:'',from:'',to:'',search:''};syncURL();render()}
function empty(a,b,act='import'){return `<div class="empty"><div class="empty-icon">◇</div><h2>${a}</h2><p>${b}</p>${act?`<button class="primary" onclick="${act==='import'?'importModal()':act}">${act==='import'?t('导入回答','Import answers'):t('开始配置','Get started')}</button>`:''}</div>`}
function table(headers,body){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`}
function overview(){const m=metric(),all=filtered();return filters()+`<div class="stats"><button class="stat" onclick="go('executions')"><div class="stat-title">${t('样本提及率','Sample mention rate')} ↗</div><div class="stat-value">${pct(m.rate)}</div><div class="stat-foot">${m.m} / ${m.valid.length} ${t('有效回答点名品牌','valid answers mention the brand')}</div></button><button class="stat" onclick="go('citations')"><div class="stat-title">${t('自有引用覆盖率','Owned citation coverage')} ↗</div><div class="stat-value">${pct(m.own)}</div><div class="stat-foot">${m.o} / ${m.cap.length} ${t('引用可观察回答','citation-observable answers')}</div></button><button class="stat" onclick="go('knowledge')"><div class="stat-title">${t('待确认事实','Facts awaiting review')} ↗</div><div class="stat-value">${rows('facts').filter(f=>f.status!=='approved').length}</div><div class="stat-foot">${t('人工确认适用范围与来源','Review source and applicable scope')}</div></button><button class="stat" onclick="go('content')"><div class="stat-title">${t('待审核内容','Content awaiting review')} ↗</div><div class="stat-value">${rows('artifacts').filter(a=>a.status==='in_review').length}</div><div class="stat-foot">${t('按具体内容版本审核','Review exact content versions')}</div></button></div><div class="grid"><section class="card"><div class="card-head"><h2>${t('品牌提及趋势','Brand mention trend')}</h2><span class="tag">${t('按日 · 点选下钻','Daily · Click to explore')}</span></div>${all.length?trend(all):empty(t('尚无回答数据','No answer data yet'),t('导入首批回答后查看真实计算结果','Import answers to calculate your first metrics'))}<div class="legend"><span><i class="dot"></i>${esc(workspace().brand)}</span><span>${t('失败样本不进入提及率分母','Failed samples excluded from the denominator')}</span></div></section><section class="card"><div class="card-head"><h2>${t('AI 产品模式表现','Performance by AI mode')}</h2><span class="muted small">${t('提及率','Mention rate')}</span></div>${platforms(all)}<p class="subtitle">${t('模式名称来自导入记录，不代表接口已接通。','Mode names come from imported records, not live connections.')}</p></section></div><section class="card table-card"><div class="card-head"><h2>${t('追踪中的购买问题','Tracked purchase questions')}</h2><a href="#/w/${ws}/prompts">${t('查看全部','View all')} →</a></div>${promptTable(true)}</section><div class="footer"><span>${t('数据版本','Dataset')} v${data.revision} · metric_v1 · ${workspace().demo?'DEMO':t('人工导入','Manual import')}</span><span>${m.valid.length} ${t('有效','valid')} / ${all.length} ${t('已导入记录','imported records')} · ${m.failed} ${t('失败','failed')} · ${t('计划采样覆盖率未知','Planned collection coverage unknown')}</span></div>`}
function trend(all){const dates=[...new Set(all.map(a=>a.collected_at.slice(0,10)))].sort(),vals=dates.map(d=>metric(all.filter(a=>a.collected_at.startsWith(d))).rate),x=i=>55+i*(550/Math.max(1,dates.length-1)),y=v=>180-(v||0)*145;return `<svg class="chart" viewBox="0 0 660 220" role="img" aria-label="${t('每日样本提及率','Daily sample mention rate')}"><defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#a99aeb" stop-opacity=".2"/><stop offset="100%" stop-color="#a99aeb" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(v=>`<path d="M45 ${y(v/100)}H625" stroke="#eff0f5" stroke-dasharray="3 4"/><text x="8" y="${y(v/100)+4}">${v}%</text>`).join('')}<path d="M${x(0)},180 ${vals.map((v,i)=>`L${x(i)},${y(v)}`).join(' ')} L${x(dates.length-1)},180 Z" fill="url(#fade)"/><path class="line" d="${vals.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ')}"/>${dates.map((d,i)=>`<circle class="point" tabindex="0" role="button" aria-label="${d} ${pct(vals[i])}" cx="${x(i)}" cy="${y(vals[i])}" r="4" onclick="day('${d}')" onkeydown="if(event.key==='Enter')day('${d}')"/><text x="${x(i)-12}" y="210">${d.slice(5)}</text>`).join('')}</svg><details><summary class="muted small">${t('查看图表数据表','View chart data table')}</summary>${table([t('日期','Date'),t('提及率','Mention rate')],dates.map((d,i)=>`<tr><td><button class="link" onclick="day('${d}')">${d}</button></td><td>${pct(vals[i])}</td></tr>`).join(''))}</details>`}
function day(d){filter.from=d;filter.to=d;go('executions');render()}
function platforms(all){return [...new Set(all.map(a=>a.platform))].map((p,i)=>{let m=metric(all.filter(a=>a.platform===p));return `<div class="platform-row"><div class="platform-info"><button class="link ghost small" onclick="filter.platform=decodeURIComponent('${enc(p)}');go('executions');render()">${esc(p)}</button><span>${pct(m.rate)} <span class="muted">· ${m.m}/${m.valid.length}</span></span></div><div class="bar"><i style="width:${(m.rate||0)*100}%;background:${['#7460dc','#4b9a8d','#6f9ed8','#c29868'][i%4]}"></i></div></div>`}).join('')||empty(t('等待导入','Awaiting import'),t('国内外样本分别计算','Markets are calculated separately'),'')}
function promptTable(short=false){let ps=rows('prompts').filter(p=>p.market===filter.market&&(!filter.search||p.text.toLowerCase().includes(filter.search.toLowerCase())));if(short)ps=ps.slice(0,5);return ps.length?table([t('问题','Question'),t('主题 / 语言','Topic / language'),t('有效回答','Valid answers'),t('提及率','Mention rate'),t('状态','Status')],ps.map(p=>{const m=metric(filtered().filter(a=>a.prompt_id===p.id));return `<tr><td><button class="link" onclick="promptDetail('${p.id}')">${esc(p.text)}</button><div class="row-meta">v${p.version} · ${t('无品牌发现题','Unbranded discovery')}</div></td><td>${esc(p.topic)}<div class="row-meta">${esc(p.locale)} · ${p.market.toUpperCase()}</div></td><td><button class="ghost small" onclick="promptDetail('${p.id}')">${m.valid.length} ↗</button></td><td>${pct(m.rate)}</td><td><span class="${p.active?'badge':'tag warn'}">${p.active?t('启用','Active'):t('暂停','Paused')}</span></td></tr>`}).join('')):empty(t('还没有问题','No prompts yet'),t('添加问题或导入带问题字段的回答','Add a prompt or import answers with question fields'),"promptModal()")}
function executions(list=filtered()){return table([t('问题 / 采样时间','Question / sampled at'),t('AI 产品模式','AI product mode'),t('来源','Source'),t('状态','Status'),t('品牌点名','Brand mention'),t('引用','Citations')],list.map(a=>`<tr><td><button class="link" onclick="answer('${a.id}')">${esc(a.prompt_text)}</button><div class="row-meta">${esc(a.collected_at)} · ${a.market.toUpperCase()} · ${esc(a.locale)}</div></td><td>${esc(a.platform)}</td><td><span class="tag ${a.source_type==='demo'?'warn':''}">${a.source_type==='demo'?'Demo':t('人工导入','Manual import')}</span></td><td>${a.status==='success'?`<span class="check">● ${t('有效','Valid')}</span>`:`<span class="error">× ${t('失败','Failed')}</span>`}</td><td>${a.status==='success'?(mentioned(a)?t('已提及','Mentioned'):t('未提及','Absent')):'—'}</td><td>${a.citation_supported===false?t('不可观察','Unavailable'):citations(a).length}</td></tr>`).join(''))}
function citationPage(){const map=new Map();for(const a of metric().valid)for(const c of citations(a)){if(!map.has(c.url))map.set(c.url,{...c,answers:[],owned:owned(c)});map.get(c.url).answers.push(a.id)}return filters()+`<div class="card table-card"><div class="card-head"><h2>${t('来源页面','Source pages')}</h2><span class="muted">${map.size} URLs</span></div>${map.size?table([t('页面与域名','Page / domain'),t('关系','Relationship'),t('覆盖回答','Answer coverage'),t('引用份额','Citation share')],[...map.values()].map(c=>`<tr><td><button class="link" onclick="sourceDetail('${enc(c.url)}')">${esc(c.title||c.url)}</button><div class="row-meta">${esc(new URL(c.url).hostname)}</div></td><td><span class="tag">${c.owned?t('自有','Owned'):t('未知 / 待分类','Unknown / unclassified')}</span></td><td>${c.answers.length}</td><td>${pct(c.answers.length/[...map.values()].reduce((s,c)=>s+c.answers.length,0))}</td></tr>`).join('')):empty(t('没有可观察引用','No observable citations'),t('只有实际提供的引用才会进入统计','Only supplied citations are counted'))}</div><p class="subtitle">${t('按单条回答内 URL 去重。外部引用不自动等于独立背书；未抓取的页面没有内容快照。','URLs deduplicated within each answer. External sources are not automatically independent endorsements. Page snapshots are not connected.')}</p>`}
function sourceDetail(encoded){let url=decodeURIComponent(encoded),as=metric().valid.filter(a=>citations(a).some(c=>c.url===url));drawer(`<div class="card-head"><h2>${t('来源页面详情','Source page')}</h2><button onclick="closeOverlay()">×</button></div><p class="mono">${esc(url)}</p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${t('打开原始网站','Open original website')} ↗</a><div class="notice" style="margin-top:20px">${t('页面抓取未接入；以下仅为回答中可见的来源记录。','Page fetching is not connected. Below are visible citation records only.')}</div>${executions(as)}`)}
function markets(){return `<div class="split">${[['us','美国','United States','跨境电商','Cross-border ecommerce','en','Aster Home'],['cn','中国大陆 · 杭州','Mainland China · Hangzhou','本地门店','Local store','zh','Aster Home 体验店（虚构）']].map(([id,zh,eng,bz,be,l,b])=>`<section class="card"><div class="card-head"><h2>${en?eng:zh}</h2><span class="tag">${t('仅支持导入','Import only')}</span></div><div class="kv"><span>${t('经营场景','Business')}</span><span>${en?be:bz}</span><span>${t('示例品牌','Example brand')}</span><span>${esc(b)}</span><span>${t('问题语言','Prompt language')}</span><span>${l}</span><span>${t('采样定位','Collection location')}</span><span>${t('未提供，不推断真实定位','Unknown, no inferred geolocation')}</span></div><p class="subtitle">${t('这些是首版预设市场。品牌与域名可在设置中配置。','These are starter market profiles. Configure brand and domains in Settings.')}</p><button onclick="filter.market='${id}';filter.platform='';go('overview')">${t('查看市场结果','View market results')} →</button></section>`).join('')}</div><section class="card" style="margin-top:20px"><div class="card-head"><h2>${t('目标 AI 产品覆盖','Target AI product coverage')}</h2></div>${table([t('目标市场','Market'),t('实际入口 / 模式','Product / mode'),t('当前接入方式','Current method'),t('自动采样','Automated collection')],[['cn','豆包 · Web'],['cn','DeepSeek · Web'],['cn','Kimi · Web'],['cn','千问 · Web'],['us','ChatGPT · Search'],['us','Perplexity · Search'],['us','Google · AI Mode'],['us','Claude · Web']].map(([m,p])=>`<tr><td>${m.toUpperCase()}</td><td>${p}</td><td>${t('手工 JSON / CSV 导入','Manual JSON / CSV import')}</td><td><span class="tag warn">${t('未连接','Not connected')}</span></td></tr>`).join(''))}</section>`}
function projects(){return rows('projects').length?`<div class="split">${rows('projects').map(p=>`<article class="card"><div class="card-head"><h2>${esc(p.title)}</h2><span class="tag">${t('待调查','Triage')}</span></div><p>${esc(p.goal)}</p><div class="kv"><span>${t('证据','Evidence')}</span><span>${p.answer_id?`<button class="small" onclick="answer('${p.answer_id}')">${t('查看原始回答','View original answer')} ↗</button>`:t('手工创建 · 待补证','Manual · Evidence required')}</span><span>${t('成功 / 停止条件','Success / stop condition')}</span><span>${esc(p.stop)}</span></div><p class="subtitle">${t('缺席是观察，不是原因诊断；确认原因与依据后再起草。','Absence is an observation. Confirm evidence and diagnosis before drafting.')}</p><button onclick="draftModal('${p.id}')">${t('基于批准事实建立草稿','Draft from approved facts')} →</button></article>`).join('')}</div>`:empty(t('从一条证据开始','Start with evidence'),t('在回答详情中创建调查，或记录一项手工任务','Create an investigation from an answer or add a manual task'),"projectModal()")}
function knowledge(){return `<div class="notice">${t('事实先保存为待确认，批准后才可用于模板草稿。这里的批准为单用户开发流程，不代表多人权限已实现。','Facts require approval before use in template drafts. This is a single-user development workflow, not multi-user authorization.')}</div>${rows('facts').length?rows('facts').map(f=>`<section class="card" style="margin-bottom:15px"><div class="card-head"><h2>${esc(f.title)}</h2><span class="${f.status==='approved'?'badge':'tag warn'}">${f.status==='approved'?t('已批准','Approved'):t('待确认','Needs review')}</span></div><p>${esc(f.text)}</p><p class="subtitle">${f.market.toUpperCase()} · v${f.version} · ${t('来源','Source')}: ${esc(f.source)}</p>${f.status!=='approved'?`<button style="margin-top:15px" onclick="approveFact('${f.id}')">${t('确认来源与范围并批准','Confirm source and scope, approve')}</button>`:''}</section>`).join(''):empty(t('建立可信事实依据','Build an evidence base'),t('添加来自品牌资料的事实、来源段落与适用市场','Add brand facts, source excerpts and applicable market'),"factModal()")}`}
const statuses={draft:['草稿','Draft'],in_review:['待审核','In review'],approved:['已批准','Approved'],applied:['人工实施已记录','Manual implementation recorded']};const st=s=>statuses[s]?.[en?1:0]||s;
function content(){return rows('artifacts').length?`<section class="card table-card">${table([t('标题','Title'),t('版本','Version'),t('状态','Status'),t('目标','Target')],rows('artifacts').map(a=>`<tr><td><button class="link" onclick="artifact('${a.id}')">${esc(a.title)}</button></td><td>v${a.version}</td><td><span class="tag">${st(a.status)}</span></td><td>${esc(a.target)}</td></tr>`).join(''))}</section>`:empty(t('还没有内容草稿','No content drafts'),t('添加并批准事实后，可用受约束模板组装修改稿。模型生成尚未接入。','Approve facts, then assemble a constrained template draft. Model generation is not connected.'),"draftModal()")}
function experiments(){return rows('experiments').length?rows('experiments').map(e=>`<section class="card" style="margin-bottom:15px"><div class="card-head"><h2>${esc(e.title)}</h2><span class="tag warn">${t('计划 · 未评估效果','Planned · No effect evaluation')}</span></div><p>${esc(e.hypothesis)}</p><p class="subtitle">${t('冻结基线回答','Frozen baseline answers')}: ${e.baseline.length} · ${t('停止条件','Stop condition')}: ${esc(e.stop)}</p><p class="subtitle">${t('未接入生效验证与复测采样；没有输出因果提升结论。','Implementation verification and retest collection are not connected. No causal improvement claims.')}</p></section>`).join(''):empty(t('先冻结一份基线','Freeze a baseline first'),t('保存当前市场与样本 ID、假设和停止条件，后续接入复测。','Save market, answer IDs, hypothesis and stop condition for later retesting.'),"experimentModal()")}
function connections(){return `<div class="split">${[[t('回答数据导入','Answer imports'),t('JSON / CSV · 本地校验与存储','JSON / CSV · Local validation and storage'),true],[t('AI 采样适配器','AI collection adapters'),t('国内外实际入口需逐一验证授权与能力','Each product requires authorization and capability validation'),false],[t('CMS 与渠道','CMS & channels'),t('首版导出修改包与人工实施回执','Export change packages and record manual implementation'),false],[t('知识检索与模型','Knowledge retrieval & models'),t('当前仅支持人工事实与确定性模板组装','Manual facts and deterministic template assembly only'),false],[t('需求、商品与日志','Demand, shopping & logs'),t('未接数据源，不提供市场需求量或订单推算','No sources connected; no demand-volume or order estimates'),false]].map(([a,b,on])=>`<section class="card"><div class="card-head"><h2>${a}</h2><span class="${on?'badge':'tag warn'}">${on?t('可用','Available'):t('未连接','Not connected')}</span></div><p class="muted">${b}</p>${on?`<button onclick="importModal()">${t('打开导入','Open importer')}</button>`:''}</section>`).join('')}</div>`}
function settings(){return `<section class="card"><h2>${t('品牌与分析配置','Brand & analysis settings')}</h2><p class="muted">${t('当前为单用户开发版，服务仅绑定本机。多人登录、角色权限与生产审计尚未实现。','Single-user development build, bound to loopback. Multi-user login, roles and production audit are not implemented.')}</p><div class="kv"><span>${t('品牌','Brand')}</span><span>${esc(workspace().brand)}</span><span>${t('别名','Aliases')}</span><span>${esc(workspace().aliases.join(', '))}</span><span>${t('自有域名','Owned domains')}</span><span>${esc(workspace().domains.join(', '))||'—'}</span><span>${t('数据存储','Storage')}</span><span>${local?'SQLite · work/signal.db':t('线上 Demo · 当前会话内存，刷新重置','Online demo · Session memory, reset on refresh')}</span><span>${t('身份与权限','Identity & access')}</span><span>${t('待建设 · 请勿部署为多人服务','Pending · Do not expose as a multi-user service')}</span></div>${local&&!workspace().demo?`<button onclick="brandModal()">${t('设置品牌与域名','Configure brand & domains')}</button>`:''}<button onclick="downloadJSON(data,'signal-geo-backup.json')">${t('下载当前数据备份','Download data backup')}</button></section>`}
function render(){document.documentElement.lang=en?'en':'zh-CN';const w=workspace();$('#app').innerHTML=`<div class="layout"><aside><a class="logo" href="#/w/${ws}/overview"><span class="mark">∿</span><span style="color:#282d3b">signal<span style="color:#8272cf">geo</span></span></a><div class="workspace"><div class="muted" style="font-size:10px;margin-bottom:7px">${t('品牌工作区','BRAND WORKSPACE')}</div><select id="workspace" aria-label="${t('工作区','Workspace')}">${data.workspaces.filter(x=>local||x.demo).map(x=>`<option value="${x.id}" ${x.id===ws?'selected':''}>${esc(x.name)} ${x.demo?'· Demo':''}</option>`).join('')}</select></div><nav>${nav('overview')}${nav('research')}${nav('diagnostic')}${nav('markets')}${nav('entities')}<div class="label">${t('观察','MONITOR')}</div>${nav('visibility')}${nav('prompts')}${nav('executions')}${nav('citations')}<details ${['factcheck','sentiment','fanout','demand','shopping','traffic'].includes(page)?'open':''}><summary class="muted small" style="padding-left:14px">${t('更多观察','More analytics')}</summary>${['factcheck','sentiment','fanout','demand','shopping','traffic'].map(nav).join('')}</details><div class="label">${t('执行','WORK')}</div>${nav('projects')}${nav('content')}${nav('experiments')}<div class="label">${t('依据与配置','CONTEXT & SETTINGS')}</div>${nav('knowledge')}${nav('tools')}${nav('apis')}${nav('bai')}${nav('integrations')}${nav('settings')}</nav><div class="aside-bottom"><div class="workspace" style="margin-bottom:0"><span class="tag">BUILD 0.3</span><p class="muted" style="font-size:10px;margin-bottom:0">${t('从答案到证据，从证据到行动。','From answers to evidence. Evidence to action.')}</p></div><div class="profile"><div class="avatar">HL</div><div><b style="font-size:12px">${t('个人开发工作区','Personal workspace')}</b><div class="row-meta">${t('单用户预览','Single-user preview')}</div></div></div></div></aside><div class="shell"><header><div class="actions"><button class="mobile-menu ghost" onclick="document.body.classList.toggle('nav-open')">☰</button><span>${esc(w.name)} <span style="padding:0 10px;color:#c7cad3">/</span> ${title(page)}</span></div><div class="header-right"><span class="tag">${local?t('本地开发服务','Local dev server'):t('交互预览','Interactive preview')}</span><button class="small" id="lang">${en?'中文':'English'} ⇄</button><span class="avatar" style="font-size:10px;padding:8px">HL</span></div></header><main><div class="page-head"><div><h1>${title(page)}</h1><p class="subtitle">${t('把 AI 回答、品牌事实与每一次修改连接起来。','Connect AI answers, brand facts and every change.')}</p></div><div class="actions"><button onclick="exportReport()">↓ ${t('导出快照','Export snapshot')}</button><button class="primary" onclick="${({prompts:'promptModal()',projects:'projectModal()',knowledge:'factModal()',content:'draftModal()',experiments:'experimentModal()'})[page]||'importModal()'}">＋ ${({prompts:t('添加问题','Add prompt'),projects:t('新建项目','New project'),knowledge:t('添加事实','Add fact'),content:t('建立草稿','Create draft'),experiments:t('创建复测计划','Plan experiment')})[page]||t('导入回答','Import answers')}</button></div></div><div class="notice"><span><b>${w.demo?'DEMO · ':''}</b>${w.demo?t('当前为虚构示例工作区，回答与指标仅用于验证交互，不代表实际品牌或 AI 平台表现。','Fictional demo workspace. Answers and metrics illustrate interactions, not real brand or AI performance.'):t('真实导入工作区 · 单用户本地开发版。所有指标由当前导入记录计算，未接入自动采样。','Real imports · Single-user local development. Metrics calculated from imported records; automated collection is not connected.')}</span><a href="#/w/${ws}/integrations" style="white-space:nowrap">${t('数据能力','Capabilities')} →</a></div><div id="view">${({tools:toolCenterPage,diagnostic:diagnosticPage,overview,visibility:()=>filters()+`<div class="grid"><section class="card"><h2>${t('按日可见度','Daily visibility')}</h2>${filtered().length?trend(filtered()):empty(t('无匹配样本','No matching samples'),t('导入或重置筛选','Import data or reset filters'))}</section><section class="card"><h2>${t('平台明细','Platform breakdown')}</h2>${platforms(filtered())}</section></div><section class="card table-card">${promptTable()}</section>`,prompts:()=>filters()+`<input class="search" id="search" placeholder="${t('搜索问题…','Search prompts…')}" value="${esc(filter.search)}" style="margin-bottom:16px"><section class="card table-card">${promptTable()}</section>`,executions:()=>filters()+`<input class="search" id="search" placeholder="${t('搜索问题或原文…','Search prompts or answer text…')}" value="${esc(filter.search)}" style="margin-bottom:16px"><section class="card table-card">${filtered().length?executions():empty(t('无匹配回答','No matching answers'),t('导入回答或重置筛选后重试','Import answers or reset the filters'))}</section>`,citations:citationPage,markets,projects,knowledge,content,experiments,integrations:connections,settings,audit:()=>`<div class="card">${table([t('时间','Time'),t('动作','Action'),t('对象','Object')],rows('audit').map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.action)}</td><td>${esc(a.object)}</td></tr>`).join(''))}</div>`})[page]?.()||empty(t('此模块尚未接入','This module is not connected'),t('保留产品入口，当前没有采样、分析或写入能力。请先使用回答导入、证据下钻和人工事实流程。','This module has no collection, analysis or write capability yet. Start with answer imports, evidence drilldowns and manual facts.'),"go('integrations')")}</div><div class="footer"><a href="#/w/${ws}/audit">${t('查看开发操作记录','View development activity')} →</a><span>Signal GEO · ${t('证据先于结论','Evidence before conclusions')} · v0.1</span></div></main></div></div>`;$('#lang').onclick=()=>{en=!en;localStorage.setItem('signal-ui',en?'en':'zh');const snap=captureForm();render();if($('#overlay').innerHTML){const active=$('#overlay').dataset.kind;if(active==='answer')answer($('#overlay').dataset.id,false);else if(active==='artifact')artifact($('#overlay').dataset.id,false);else if(active){closeOverlay();window[active]?.();restoreForm(snap)}restoreForm(snap)}};$('#workspace').onchange=e=>{ws=e.target.value;filter={market:'us',platform:'',search:'',from:'',to:''};closeOverlay();go('overview')};for(const k of ['market','platform','from','to'])if($('#'+k))$('#'+k).onchange=e=>{filter[k]=e.target.value;if(k==='market'){filter.platform='';if(ws==='demo'){/* separate fictional brand by market */}}syncURL();render()};if($('#search'))$('#search').onchange=e=>{filter.search=e.target.value;syncURL();render()};document.body.classList.remove('nav-open')}
function captureForm(){return [...document.querySelectorAll('#overlay input,#overlay textarea,#overlay select')].map(e=>({id:e.id,value:e.value}))}function restoreForm(s){s.forEach(x=>{if($('#'+x.id))$('#'+x.id).value=x.value})}
function overlay(html,modal=false,kind='',id=''){lastFocus=document.activeElement;$('#overlay').dataset.kind=kind;$('#overlay').dataset.id=id;$('#overlay').innerHTML=`<div class="scrim ${modal?'modal-wrap':''}"><section class="${modal?'modal':'drawer'}" role="dialog" aria-modal="true" aria-label="${t('详情与操作','Details and actions')}" tabindex="-1">${html}</section></div>`;document.body.style.overflow='hidden';$('.scrim').onclick=e=>{if(e.target===e.currentTarget)closeOverlay()};$('.scrim section').focus()}
const drawer=(html,kind='',id='')=>overlay(html,false,kind,id),modal=(html,kind='')=>overlay(html,true,kind);
function closeOverlay(updateURL=true){const had=!!$('#overlay').innerHTML;$('#overlay').innerHTML='';$('#overlay').dataset.kind='';document.body.style.overflow='';if(had&&lastFocus?.isConnected)lastFocus.focus();const u=new URL(location);if(updateURL&&u.hash.includes('?')){const q=new URLSearchParams(u.hash.split('?')[1]);q.delete('answer');history.replaceState(null,'',u.pathname+u.search+u.hash.split('?')[0]+(q.size?'?'+q:''))}}
function overlayTabStops(dialog){return [...dialog.querySelectorAll('button,a[href],input,textarea,select,summary,[tabindex],[contenteditable="true"]')].filter(el=>{
 if(el.tabIndex<0||el.matches(':disabled')||el.closest('[inert]')||!el.getClientRects().length||getComputedStyle(el).visibility==='hidden')return false;
 // Chromium can report layout rects for content hidden by a closed details.
 for(let parent=el.parentElement;parent&&parent!==dialog;parent=parent.parentElement){
  if(parent.matches('details:not([open])')){const summary=[...parent.children].find(child=>child.tagName==='SUMMARY');if(!summary?.contains(el))return false}
 }
 return true;
})}
document.addEventListener('keydown',e=>{
 const dialog=document.querySelector('#overlay [role="dialog"]');if(!dialog)return;
 if(e.key==='Escape'){e.preventDefault();closeOverlay();return}
 if(e.key!=='Tab')return;
 const stops=overlayTabStops(dialog),active=document.activeElement;
 if(!stops.length){e.preventDefault();dialog.focus();return}
 if(!stops.includes(active)){e.preventDefault();(e.shiftKey?stops.at(-1):stops[0]).focus();return}
 if(e.shiftKey&&active===stops[0]){e.preventDefault();stops.at(-1).focus()}
 else if(!e.shiftKey&&active===stops.at(-1)){e.preventDefault();stops[0].focus()}
});
function answer(id,url=true){let a=rows('answers').find(a=>a.id===id);if(!a)return;if(url)history.replaceState(null,'',`#/w/${ws}/${page}?${query()}&answer=${enc(id)}`);drawer(`<div class="card-head"><div><span class="tag">${a.source_type==='demo'?'DEMO':t('人工导入','Manual import')}</span><h2 style="margin-top:10px">${t('原始回答与引用','Original answer & citations')}</h2></div><button onclick="closeOverlay()" aria-label="${t('关闭','Close')}">×</button></div><p style="font-weight:600">${esc(a.prompt_text)}</p><div class="kv"><span>${t('AI 产品模式','AI product mode')}</span><span>${esc(a.platform)}</span><span>${t('采样时间','Collected at')}</span><span>${esc(a.collected_at)}</span><span>${t('目标市场 / 语言','Target market / language')}</span><span>${a.market.toUpperCase()} / ${esc(a.locale)}</span><span>${t('实际采集环境','Actual collection region')}</span><span>${esc(a.collection_region)||t('未提供 · 不推断 GPS 定位','Not supplied · No inferred GPS location')}</span><span>${t('原始记录','Original record')}</span><span class="mono">${esc(a.id)} · prompt v${a.prompt_version||1}</span></div><div class="tabs"><button class="selected" onclick="$('#rawtext').hidden=false;$('#rawjson').hidden=true">${t('原文','Original')}</button><button onclick="$('#rawtext').hidden=true;$('#rawjson').hidden=false">JSON</button></div><div class="evidence" id="rawtext">${esc(a.raw_answer)||t('采集失败，没有原文','Collection failed, no answer text')}</div><pre class="evidence" hidden id="rawjson">${esc(JSON.stringify(a,null,2))}</pre><h3 style="margin-top:25px">${t('可见引用','Visible citations')} · ${citations(a).length}</h3>${citations(a).map((c,i)=>`<div class="source"><b>[${i+1}] ${esc(c.title||t('未提供标题','Untitled'))}</b><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.url)} ↗</a><span class="tag">${owned(c)?t('自有域名','Owned domain'):t('外部来源 · 关系未知','External · Relationship unknown')}</span>${c.support?`<p>${t('导入的支持句','Supplied support text')}: ${esc(c.support)}</p>`:`<p class="muted">${t('未提供支持句锚点','Supporting sentence anchor not supplied')}</p>`}</div>`).join('')||`<p class="muted">${a.citation_supported===false?t('该来源未提供引用观察能力','This source does not expose citations'):t('该记录未提供引用','No citations supplied')}</p>`}<div class="actions" style="margin-top:25px"><button class="primary" onclick="projectModal('${a.id}')">${t('基于此回答创建调查','Investigate this answer')}</button><button onclick="downloadJSON(rows('answers').find(a=>a.id==='${a.id}'),'answer-${a.id}.json')">${t('下载原始记录','Download record')}</button></div>`, 'answer',id)}
function promptDetail(id){let p=rows('prompts').find(p=>p.id===id);drawer(`<div class="card-head"><h2>${t('问题分析','Prompt analysis')}</h2><button onclick="closeOverlay()">×</button></div><p>${esc(p.text)}</p><p class="subtitle">v${p.version} · ${esc(p.topic)} · ${p.market.toUpperCase()} · ${esc(p.locale)}</p><div class="actions" style="margin:20px 0"><button onclick="promptModal('${id}')">${t('编辑为新版本','Edit as new version')}</button><button onclick="mutate('toggle_prompt',{id:'${id}'}).then(()=>promptDetail('${id}'))">${p.active?t('暂停问题','Pause prompt'):t('启用问题','Activate prompt')}</button></div><p class="subtitle">${t('这里的启停仅保存题集状态；尚未连接自动调度。','Activation saves prompt state only; automated schedules are not connected.')}</p><h3 style="margin-top:20px">${t('历史回答','Historical answers')}</h3>${executions(filtered().filter(a=>a.prompt_id===id))}<h3 style="margin-top:20px">${t('旧题目版本','Previous prompt versions')}</h3>${p.history.map(h=>`<p class="muted">v${h.version} · ${esc(h.text)}</p>`).join('')||'—'}`)}
function head(s){return `<div class="card-head"><h2>${s}</h2><button type="button" onclick="closeOverlay()">×</button></div>`}
function input(label,id,value='',type='text'){return `<label for="${id}">${label}</label><input required id="${id}" type="${type}" value="${esc(value)}">`}function area(label,id,value=''){return `<label for="${id}">${label}</label><textarea required id="${id}">${esc(value)}</textarea>`}function submit(s){return `<div class="actions" style="margin-top:22px"><button class="primary" type="submit">${s}</button><button type="button" onclick="closeOverlay()">${t('取消','Cancel')}</button></div>`}
function marketSelect(){return `<label for="fm">${t('适用市场','Applicable market')}</label><select id="fm"><option value="us" ${filter.market==='us'?'selected':''}>${t('美国','United States')}</option><option value="cn" ${filter.market==='cn'?'selected':''}>${t('中国大陆','Mainland China')}</option></select>`}
function promptModal(id=''){const p=rows('prompts').find(p=>p.id===id);modal(head(p?t('编辑问题 · 创建新版本','Edit prompt · New version'):t('添加购买问题','Add purchase question'))+`<form id="form">${area(t('问题原文','Prompt text'),'pt',p?.text)}${input(t('主题','Topic'),'topic',p?.topic)}${marketSelect()}${input(t('问题语言','Prompt language'),'locale',p?.locale||(filter.market==='us'?'en':'zh'))}${submit(t('保存问题','Save prompt'))}</form>`,'promptModal');$('#form').onsubmit=async e=>{e.preventDefault();if(await mutate(p?'edit_prompt':'prompt',p?{id,text:$('#pt').value}:{text:$('#pt').value,topic:$('#topic').value,market:$('#fm').value,locale:$('#locale').value,type:'discovery'})){closeOverlay();toast(t('已保存，历史回答保持原版本','Saved; historical answers retain their versions'))}}}
function projectModal(aid=''){const a=rows('answers').find(x=>x.id===aid);modal(head(t('创建调查项目','Create investigation'))+`<form id="form">${input(t('项目名称','Project title'),'pn',a?t('调查品牌缺席与来源适配','Investigate brand presence and source fit'):'')}${area(t('目标与已观察到的现象','Goal and observed evidence'),'goal',a?.prompt_text||'')}${area(t('成功与停止条件','Success and stop conditions'),'stop')}${marketSelect()}<p class="subtitle">${a?t('将保留原始回答 ID；原因尚未确认。','Original answer ID will be linked; cause remains unconfirmed.'):t('手工项目需要后续补充证据。','Manual project requires supporting evidence.')}</p>${submit(t('保存调查','Save investigation'))}</form>`,'projectModal');$('#form').onsubmit=async e=>{e.preventDefault();if(await mutate('project',{title:$('#pn').value,goal:$('#goal').value,stop:$('#stop').value,answer_id:aid||null,market:$('#fm').value})){closeOverlay();go('projects')}}}
function factModal(){modal(head(t('添加事实依据','Add source-backed fact'))+`<form id="form">${input(t('事实标题','Fact title'),'ft')}${area(t('事实内容 · 保留数值、单位与限制条件','Fact text · Retain values, units and conditions'),'ftxt')}${area(t('来源链接或文档名与原文段落','Source URL or document name and original excerpt'),'fsource')}${marketSelect()}${submit(t('保存为待确认','Save for review'))}</form>`,'factModal');$('#form').onsubmit=async e=>{e.preventDefault();if(await mutate('fact',{title:$('#ft').value,text:$('#ftxt').value,source:$('#fsource').value,market:$('#fm').value})){closeOverlay();go('knowledge')}}}
async function approveFact(id){if(await mutate('approve_fact',{id}))toast(t('已记录人工批准','Manual approval recorded'))}
function draftModal(project=''){modal(head(t('受约束的事实模板','Constrained fact template'))+`<div class="notice">${t('此操作将批准事实原文及来源 ID 组装为草稿，不调用模型、不补写产品主张。正式生成器后续接入。','Assembles approved fact text and source IDs. No model calls or invented claims. A generation adapter will be added later.')}</div><form id="form">${input(t('内容标题','Content title'),'dt')}${input(t('目标 URL 或门店字段','Target URL or listing field'),'target')}${marketSelect()}${submit(t('组装草稿','Assemble draft'))}</form>`,'draftModal');$('#form').onsubmit=async e=>{e.preventDefault();if(await mutate('draft',{title:$('#dt').value,target:$('#target').value,market:$('#fm').value,project})){closeOverlay();go('content')}}}
function artifact(id,url=true){const a=rows('artifacts').find(x=>x.id===id);if(!a)return;drawer(head(esc(a.title))+`<div class="card-head"><span class="tag">v${a.version} · ${st(a.status)}</span><button onclick="downloadJSON(rows('artifacts').find(x=>x.id==='${id}'),'change-package.json')">↓ ${t('导出修改包','Export package')}</button></div><p class="subtitle">${t('确定性模板组装；每一段保留事实 ID。保存任意修改将创建新版本并使批准失效。','Deterministic fact template; each paragraph retains its fact ID. Saving edits creates a new version and invalidates approval.')}</p>${input(t('目标','Target'),'atarget',a.target)}${area(t('正文','Content'),'abody',a.body)}<div class="actions" style="margin:16px 0"><button onclick="saveArtifact('${id}')">${t('保存新版本','Save new version')}</button>${a.status==='draft'?`<button class="primary" onclick="artifactTransition('${id}','in_review')">${t('提交审核','Submit for review')}</button>`:''}${a.status==='in_review'?`<button class="primary" onclick="artifactTransition('${id}','approved')">${t('批准当前版本','Approve this version')}</button><button onclick="artifactTransition('${id}','draft')">${t('退回草稿','Return to draft')}</button>`:''}${a.status==='approved'?`<button class="primary" onclick="receiptModal('${id}')">${t('记录人工实施','Record manual implementation')}</button>`:''}</div><div class="progress">${['draft','in_review','approved','applied'].map(s=>`<span class="${Object.keys(statuses).indexOf(a.status)>=Object.keys(statuses).indexOf(s)?'done':''}">${st(s)}</span>`).join('')}</div><h3>${t('批准事实依据','Approved fact sources')}</h3>${a.facts.map(fid=>{let f=rows('facts').find(f=>f.id===fid);return f?`<div class="item"><b>${esc(f.title)}</b><p>${esc(f.text)}</p><p class="muted">${esc(f.source)}</p><span class="mono">${f.id.slice(0,6)} · ${f.market} · v${f.version}</span></div>`:''}).join('')}${a.receipt?`<h3>${t('人工实施依据','Manual implementation evidence')}</h3><div class="evidence">${esc(a.receipt.url)}\n${esc(a.receipt.date)}\n${esc(a.receipt.evidence)}</div><p class="subtitle">${t('回执已记录，线上内容与 AI 更新尚未验证。','Receipt recorded; live content and AI updates are not verified.')}</p>`:''}<details><summary>${t('历史版本与差异','Version history & changes')}</summary>${a.history.map(h=>`<h3>v${h.version} · ${st(h.status)}</h3><pre class="evidence">${esc(h.body)}</pre>`).join('')||'—'}</details>`, 'artifact',id)}
async function saveArtifact(id){const body=$('#abody').value,target=$('#atarget').value;if(await mutate('save_artifact',{id,body,target})){artifact(id);toast(t('已保存新版本，需要重新审核','New version saved; review is required'))}}
async function artifactTransition(id,status){const a=rows('artifacts').find(a=>a.id===id);if($('#abody').value!==a.body||$('#atarget').value!==a.target){toast(t('请先保存修改，然后重新提交审核','Save changes before submitting for review'));return}if(await mutate('artifact_status',{id,status}))artifact(id)}
function receiptModal(id){modal(head(t('记录人工实施回执','Record manual implementation receipt'))+`<form id="form">${input(t('实际实施 URL','Implemented URL'),'ru','','url')}${input(t('实施时间','Implementation date'),'rd',new Date().toISOString().slice(0,10),'date')}${area(t('实施版本与可核对的文本依据','Version and verifiable implementation excerpt'),'re')}${submit(t('保存回执 · 待验证','Save receipt · Unverified'))}</form>`);$('#form').onsubmit=async e=>{e.preventDefault();if(await mutate('receipt',{id,url:$('#ru').value,date:$('#rd').value,evidence:$('#re').value})){closeOverlay();artifact(id)}}}
function experimentModal(){modal(head(t('冻结基线与复测计划','Freeze baseline & plan a retest'))+`<form id="form">${input(t('计划名称','Experiment title'),'et')}${area(t('假设与观察条件','Hypothesis and observation conditions'),'eh')}${area(t('停止条件','Stop condition'),'es')}<p class="muted">${t('冻结当前筛选下有效回答','Freeze valid answers matching current filters')}: ${metric().valid.length} · ${filter.market.toUpperCase()}</p>${submit(t('保存计划','Save plan'))}</form>`,'experimentModal');$('#form').onsubmit=async e=>{e.preventDefault();if(await mutate('experiment',{title:$('#et').value,hypothesis:$('#eh').value,stop:$('#es').value,market:filter.market,baseline:metric().valid.map(a=>a.id),filters:{...filter}})){closeOverlay();go('experiments')}}}
function brandModal(){modal(head(t('设置品牌与自有域名','Brand & owned domains'))+`<form id="form">${input(t('品牌名称','Brand name'),'bn',workspace().brand)}${input(t('别名，逗号分隔','Aliases, comma separated'),'ba',workspace().aliases.join(','))}${input(t('自有域名，逗号分隔','Owned domains, comma separated'),'bd',workspace().domains.join(','))}<p class="subtitle">${t('配置更新会创建分析修订；已导出的快照不变。','Configuration updates create an analysis revision; exported snapshots stay unchanged.')}</p>${submit(t('保存配置','Save configuration'))}</form>`);$('#bd').required=false;$('#form').onsubmit=async e=>{e.preventDefault();if(await mutate('brand',{brand:$('#bn').value,aliases:$('#ba').value.split(',').map(s=>s.trim()).filter(Boolean),domains:$('#bd').value.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean)}))closeOverlay()}}
function downloadJSON(d,name){const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportReport(){const m=metric();downloadJSON({product:'Signal GEO',demo:workspace().demo,workspace:ws,computed_at:now(),dataset_version:data.revision,metric_version:'v1',filters:{...filter},mention:{numerator:m.m,denominator:m.valid.length,value:m.rate},owned_citation_coverage:{numerator:m.o,denominator:m.cap.length,value:m.own},excluded_failed:m.failed,planned_coverage:null,answer_ids:filtered().map(a=>a.id),warning:workspace().demo?'SYNTHETIC DEMO — NOT CLIENT PERFORMANCE':'Single-user development report; no collection coverage or causal inference'},workspace().demo?'DEMO-report.json':'signal-report.json')}
function csvParse(s){s=s.replace(/^\uFEFF/,'');const out=[];let row=[],field='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){field+='"';i++}else q=!q}else if(c===','&&!q){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&s[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))out.push(row);row=[];field=''}else field+=c}if(q)throw Error(t('CSV 引号未闭合','Unclosed CSV quote'));row.push(field);if(row.some(Boolean))out.push(row);const headers=out.shift();if(!headers)throw Error('Empty CSV');return out.map(r=>Object.fromEntries(headers.map((h,i)=>[h.trim(),r[i]??''])))}
function template(){downloadJSON([{external_id:'your-record-001',prompt_text:'Which refill products fit my needs?',topic:'Purchase research',market:'us',locale:'en',platform:'Your product · Actual mode',collected_at:'2026-10-18T12:00:00Z',status:'success',raw_answer:'Paste the original answer here.',citation_supported:true,collection_region:null,citations:[{url:'https://your-brand.example/product',title:'Original source title',support:'Original supporting sentence, if available.'}]}],'answer-import-template.json')}
function importModal(){preview=[];modal(head(t('导入回答 · 校验与预览','Import answers · Validate & preview'))+`<p class="subtitle">${t('必需字段：prompt_text、topic、market、locale、platform、collected_at、status、raw_answer。market 支持 us / cn；status 为 success / failed。JSON citations 为数组，CSV 单元格需为 JSON 字符串。','Required: prompt_text, topic, market, locale, platform, collected_at, status, raw_answer. market: us / cn; status: success / failed. JSON citations use an array; a CSV citations cell contains a JSON string.')}</p><div class="actions" style="margin:16px 0"><button onclick="template()">↓ ${t('下载 JSON 模板','Download JSON template')}</button><input id="file" type="file" accept=".json,.csv" aria-label="${t('选择导入文件','Choose import file')}"></div>${area(t('或粘贴 JSON 数组 / CSV','Or paste a JSON array / CSV'),'importText')}<div class="actions" style="margin-top:15px"><button class="primary" onclick="validateImport()">${t('校验并预览','Validate & preview')}</button></div><div id="preview" style="margin-top:20px"></div>`,'importModal');$('#file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>8*1024*1024){toast(t('文件上限为 8 MB','File limit is 8 MB'));return}$('#importText').value=await f.text()}}}
function validateImport(){try{const text=$('#importText').value.trim(),arr=text.startsWith('[')?JSON.parse(text):csvParse(text);if(!Array.isArray(arr)||arr.length>5000)throw Error(t('请提供最多 5000 行的数组','Provide an array with at most 5000 rows'));preview=arr.map((a,i)=>{try{for(const k of ['prompt_text','topic','market','locale','platform','collected_at','status'])if(typeof a[k]!=='string'||!a[k].trim())throw Error(k+t(' 必填',' is required'));if(!['us','cn'].includes(a.market))throw Error('market: us / cn');if(!['success','failed'].includes(a.status))throw Error('status: success / failed');if(a.status==='success'&&(!a.raw_answer||typeof a.raw_answer!=='string'))throw Error('raw_answer required');if(!/^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(a.collected_at)||isNaN(Date.parse(a.collected_at)))throw Error('collected_at: ISO 8601 + timezone');let c=typeof a.citations==='string'?JSON.parse(a.citations||'[]'):(a.citations||[]);if(!Array.isArray(c)||c.some(x=>typeof x.url!=='string'||!safeURL(x.url)))throw Error(t('引用必须为 HTTP(S) URL 数组','Citations must contain HTTP(S) URLs'));return{row:i+1,ok:true,data:{...a,citations:c,citation_supported:a.citation_supported===true||a.citation_supported==='true',source_type:'manual_import'}}}catch(e){return{row:i+1,ok:false,error:e.message}}});$('#preview').innerHTML=`<p>${preview.filter(x=>x.ok).length} ${t('有效行','valid rows')} · ${preview.filter(x=>!x.ok).length} ${t('失败行','invalid rows')}</p>${table([t('行','Row'),t('问题 / 错误','Question / error'),t('结果','Result')],preview.slice(0,50).map(r=>`<tr><td>${r.row}</td><td>${esc(r.ok?r.data.prompt_text:r.error)}</td><td>${r.ok?'✓':'×'}</td></tr>`).join(''))}<p class="subtitle">${t('成功行独立导入；无效行跳过并可下载结果。原文与相同采样条件完全一致的记录自动去重。','Valid rows are imported independently; invalid rows are skipped. Identical answer text and sampling conditions are deduplicated.')}</p><div class="actions"><button class="primary" onclick="commitImport()" ${preview.some(r=>r.ok)?'':'disabled'}>${t('确认导入有效行','Confirm valid rows')}</button><button onclick="downloadJSON(preview.filter(r=>!r.ok),'import-errors.json')">${t('下载错误清单','Download errors')}</button></div>`}catch(e){toast(e.message)}}
async function commitImport(){const valid=preview.filter(r=>r.ok).map(r=>r.data);if(!local){toast(t('线上 Demo 不接收真实文件；请在本地服务的真实工作区导入。','Online demo does not accept real imports; use the local real workspace.'));return}if(workspace().demo){toast(t('请先切换到“我的品牌”真实工作区，避免混入示例。','Switch to the real workspace first to avoid mixing demo data.'));return}if(await mutate('import',{rows:valid})){closeOverlay();toast(t('导入已完成，重复记录已跳过','Import complete; duplicate records skipped'));go('overview')}}
function route(){let [path,q]=location.hash.slice(1).split('?'),parts=(path||'').split('/');ws=data.workspaces.some(w=>w.id===parts[2]&&(local||w.demo))?parts[2]:'demo';page=names[parts[3]]?parts[3]:'research';render();const params=new URLSearchParams(q);for(const k of ['market','platform','search','from','to'])if(params.has(k))filter[k]=params.get(k);render();if(params.has('answer'))answer(params.get('answer'),false)}
async function init(){data=seed();try{const r=await fetch('/api/bootstrap');if(r.ok&&r.headers.get('content-type')?.includes('application/json')){const j=await r.json();if(j.workspaces){local=true;if(!j.seeded){await fetch('/api/seed',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});data=await(await fetch('/api/bootstrap')).json()}else data=j}}}catch{}route();window.addEventListener('hashchange',()=>{closeOverlay(false);route()})}
